mapper.select:
SELECT id, user_id, activity_id, day, day_count, day_count_surplus, create_time, update_time
FROM raffle_activity_account_day
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND day = #{day}

mapper.update:
UPDATE raffle_activity_account_day
SET day_count_surplus = day_count_surplus - 1,
    update_time = NOW()
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND day = #{day}
  AND day_count_surplus > 0

UPDATE raffle_activity_account_day
SET day_count = day_count + #{dayCount},
    day_count_surplus = day_count_surplus + #{dayCountSurplus},
    update_time = NOW()
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND day = #{day}
